/* USER CODE BEGIN */
static bool gp29_pressed = false;

void keyboard_post_init_user(void) {
    // GP29を入力モードにし、内蔵プルアップを有効化する
    setPinInputHigh(GP29);
}

void matrix_scan_user(void) {
    // スイッチが押されてピンがLOW（GND落ち）になったとき
    if (!readPin(GP29)) {
        if (!gp29_pressed) {
            gp29_pressed = true;
            // ミュート / ミュート解除のメディアキー送信
            tap_code(KC_AUDIO_MUTE);
        }
    } else {
        // スイッチが離されたとき
        if (gp29_pressed) {
            gp29_pressed = false;
        }
    }
}

bool process_record_user(uint16_t keycode, keyrecord_t *record) {
    switch (keycode) {
        case LAYER_INFO:
            if (record->event.pressed) {
                // 現在のデフォルトレイヤーに応じた文章を入力する
                if (get_highest_layer(default_layer_state) == 3) {
                    SEND_STRING("The default layer is 3 for macOS.");
                } else {
                    SEND_STRING("The default layer is 0 for Windows and other operating systems.");
                }
            }
            return false;

        case MAC_SCREENSHOT:
            if (record->event.pressed) {
                // Shift + Command + Control を押す
                register_code(KC_LSFT);
                register_code(KC_LGUI);
                register_code(KC_LCTL);

                wait_ms(10);

                // 4を押して離す
                tap_code(KC_4);

                // 修飾キーを離す
                unregister_code(KC_LCTL);
                unregister_code(KC_LGUI);
                unregister_code(KC_LSFT);
            }
            return false;
    }

    return true;
}

// 接続先OSに応じてデフォルトレイヤーを切り替える
// Mac(macOS / iOS) -> レイヤー3、それ以外 -> レイヤー0
void housekeeping_task_user(void) {
    static os_variant_t applied_os = OS_UNSURE;
    os_variant_t os = detected_host_os();
    if (os != applied_os) {
        applied_os = os;
        if (os == OS_MACOS || os == OS_IOS) {
            default_layer_set(1UL << 3);
        } else {
            default_layer_set(1UL << 0);
        }
    }
}

